{"query":"
        query Issues {
          issues(, first: 50) {
            nodes {
              id
              identifier
              title
              description
              priority
              state {
                name
                type
              }
              assignee {
                id
                name
                email
              }
              team {
                id
                name
              }
              url
              createdAt
              updatedAt
            }
          }
        }
      "}

